"""The truth's source-map decoder: generated byte offset -> (source, original line, original column).

Scorer 6 (exp107) reads a source map as the v3 spec writes it, two corrections over scorer 4's decoder
(origins.segments / exp095 truth.py `segments`, which this reproduces exactly with both off):

  utf16     a generated column counts UTF-16 code units. Scorer 4 read it as a code-point index, so every astral
            character before a mapping on its line (an emoji in a string literal) moved that mapping one byte to
            the right of where the bundler put it, cumulatively: on a terser-minified webpack bundle (a few lines of
            megabytes) 2.09M of 2.44M segments landed on the wrong bytes, crediting library code to whatever source
            the drifted mapping named (the app's entry, in exp107's dev builds).
  unmapped  a one-field segment (a generated column and nothing else) says "this code maps to no source": the
            bundler's own glue (webpack's module wrappers, terser's joins). Scorer 4 dropped it, so the glue was
            credited to the mapping before it. Kept, as source None. Through a composed map (`inner`), a position
            the inner map does not cover, or covers with a one-field segment, is None too (scorer 4 dropped it).
"""
import bisect

B64 = {c: i for i, c in enumerate("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/")}


def vlq(seg):
    out, val, shift = [], 0, 0
    for ch in seg:
        d = B64[ch]
        val += (d & 31) << shift
        if d & 32:
            shift += 5
        else:
            out.append(-(val >> 1) if val & 1 else val >> 1)
            val, shift = 0, 0
    return out


def decode(smap, unmapped):
    """Per generated line: [(col, src, oline, ocol)]; a one-field segment is (col, None, None, None) when
    `unmapped`, else dropped (exp095 truth.decode)."""
    out, src, ol, oc = [], 0, 0, 0
    for group in smap["mappings"].split(";"):
        col, row = 0, []
        for seg in filter(None, group.split(",")):
            v = vlq(seg)
            col += v[0]
            if len(v) >= 4:
                src += v[1]
                ol += v[2]
                oc += v[3]
                row.append((col, src, ol, oc))
            elif unmapped:
                row.append((col, None, None, None))
        out.append(row)
    return out


class _Line:
    """Generated column -> byte offset within one line, walked forward (columns ascend within a line; a step back
    restarts from the line start)."""

    def __init__(self, line, utf16):
        self.ascii = line.isascii()
        self.line = line
        self.utf16 = utf16
        if utf16 and not self.ascii:
            self.u16 = line.encode("utf-16-le", "surrogatepass")
        self.pc, self.pb = 0, 0

    def byte(self, col):
        if self.ascii:
            return col
        if col < self.pc:
            self.pc, self.pb = 0, 0
        if self.utf16:
            piece = self.u16[2 * self.pc:2 * col].decode("utf-16-le", "surrogatepass")
        else:
            piece = self.line[self.pc:col]
        self.pb += len(piece.encode("utf-8", "surrogatepass"))
        self.pc = col
        return self.pb


def segments(text, smap, inner=None, utf16=True, unmapped=True):
    """[(byte offset, src, oline, ocol)] in generated order, through `inner` = (map, line offset) when given; src
    is None where the map says the code maps to nothing (only with `unmapped`)."""
    lines = text.split("\n")
    rows = decode(smap, unmapped)
    ilines = decode(inner[0], unmapped) if inner else None
    icols = {}
    out, start = [], 0
    for li, row in enumerate(rows):
        line = lines[li] if li < len(lines) else ""
        at = _Line(line, utf16)
        for col, src, ol, oc in row:
            off = start + at.byte(col)
            if ilines is not None and src is not None:
                il = ol - inner[1]
                if il < 0 or il >= len(ilines) or not ilines[il]:
                    if unmapped:
                        out.append((off, None, None, None))
                    continue
                if il not in icols:
                    icols[il] = [x[0] for x in ilines[il]]
                # the last inner segment at or before the column (scorer 4: the first one when none is)
                hit = ilines[il][max(bisect.bisect_right(icols[il], oc) - 1, 0)]
                if hit[1] is None:
                    out.append((off, None, None, None))
                    continue
                src, ol, oc = hit[1:]
            out.append((off, src, ol, oc))
        start += len(line.encode("utf-8", "surrogatepass")) + 1
    return out
